mkitem!{mkenum!{# [doc = " Represents the \"flavors\" of MIR."] # [doc = ""] # [doc = " The MIR pipeline is structured into a few major dialects, with one or more phases within each"] # [doc = " dialect. A MIR flavor is identified by a dialect-phase pair. A single `MirPhase` value"] # [doc = " specifies such a pair. All flavors of MIR use the same data structure to represent the program."] # [doc = ""] # [doc = " Different MIR dialects have different semantics. (The differences between dialects are small,"] # [doc = " but they do exist.) The progression from one MIR dialect to the next is technically a lowering"] # [doc = " from one IR to another. In other words, a single well-formed [`Body`](crate::mir::Body) might"] # [doc = " have different semantic meaning and different behavior at runtime in the different dialects."] # [doc = " The specific differences between dialects are described on the variants below."] # [doc = ""] # [doc = " Phases exist only to place restrictions on what language constructs are permitted in"] # [doc = " well-formed MIR, and subsequent phases mostly increase those restrictions. I.e. to convert MIR"] # [doc = " from one phase to the next might require removing/replacing certain MIR constructs."] # [doc = ""] # [doc = " When adding dialects or phases, remember to update [`MirPhase::index`]."] # [derive (Copy , Clone , TyEncodable , TyDecodable , Debug , PartialEq , Eq , PartialOrd , Ord)] # [derive (HashStable)] pub enum MirPhase { # [doc = " The \"built MIR\" dialect, as generated by MIR building."] # [doc = ""] # [doc = " The only things that operate on this dialect are unsafeck, the various MIR lints, and const"] # [doc = " qualifs."] # [doc = ""] # [doc = " This dialect has just the one (implicit) phase, which places few restrictions on what MIR"] # [doc = " constructs are allowed."] Built , # [doc = " The \"analysis MIR\" dialect, used for borrowck and friends."] # [doc = ""] # [doc = " The only semantic difference between built MIR and analysis MIR relates to constant"] # [doc = " promotion. In built MIR, sequences of statements that would generally be subject to"] # [doc = " constant promotion are semantically constants, while in analysis MIR all constants are"] # [doc = " explicit."] # [doc = ""] # [doc = " The result of const promotion is available from the `mir_promoted` and `promoted_mir`"] # [doc = " queries."] # [doc = ""] # [doc = " The phases of this dialect are described in `AnalysisPhase`."] Analysis (AnalysisPhase) , # [doc = " The \"runtime MIR\" dialect, used for CTFE, optimizations, and codegen."] # [doc = ""] # [doc = " The semantic differences between analysis MIR and runtime MIR are as follows."] # [doc = ""] # [doc = " - Drops: In analysis MIR, `Drop` terminators represent *conditional* drops; roughly"] # [doc = "   speaking, if dataflow analysis determines that the place being dropped is uninitialized,"] # [doc = "   the drop will not be executed. The exact semantics of this aren't written down anywhere,"] # [doc = "   which means they are essentially \"what drop elaboration does.\" In runtime MIR, the drops"] # [doc = "   are unconditional; when a `Drop` terminator is reached, if the type has drop glue that"] # [doc = "   drop glue is always executed. This may be UB if the underlying place is not initialized."] # [doc = " - Packed drops: Places might in general be misaligned - in most cases this is UB, the"] # [doc = "   exception is fields of packed structs. In analysis MIR, `Drop(P)` for a `P` that might be"] # [doc = "   misaligned for this reason implicitly moves `P` to a temporary before dropping. Runtime"] # [doc = "   MIR has no such rules, and dropping a misaligned place is simply UB."] # [doc = " - Async drops: after drop elaboration some drops may become async (`drop`, `async_fut` fields)."] # [doc = "   StateTransform pass will expand those async drops or reset to sync."] # [doc = " - Unwinding: in analysis MIR, unwinding from a function which may not unwind aborts. In"] # [doc = "   runtime MIR, this is UB."] # [doc = " - Retags: If `-Zmir-emit-retag` is enabled, analysis MIR has \"implicit\" retags in the same"] # [doc = "   way that Rust itself has them. Where exactly these are is generally subject to change,"] # [doc = "   and so we don't document this here. Runtime MIR has most retags explicit (though implicit"] # [doc = "   retags can still occur at `Rvalue::{Ref,AddrOf}`)."] # [doc = " - Coroutine bodies: In analysis MIR, locals may actually be behind a pointer that user code"] # [doc = "   has access to. This occurs in coroutine bodies. Such locals do not behave like other"] # [doc = "   locals, because they e.g. may be aliased in surprising ways. Runtime MIR has no such"] # [doc = "   special locals. All coroutine bodies are lowered and so all places that look like locals"] # [doc = "   really are locals."] # [doc = ""] # [doc = " Also note that the lint pass which reports eg `200_u8 + 200_u8` as an error is run as a part"] # [doc = " of analysis to runtime MIR lowering. To ensure lints are reported reliably, this means that"] # [doc = " transformations that can suppress such errors should not run on analysis MIR."] # [doc = ""] # [doc = " The phases of this dialect are described in `RuntimePhase`."] Runtime (RuntimePhase) , }}}
mkitem!{mkenum!{# [doc = " See [`MirPhase::Analysis`]."] # [derive (Copy , Clone , TyEncodable , TyDecodable , Debug , PartialEq , Eq , PartialOrd , Ord)] # [derive (HashStable)] pub enum AnalysisPhase { Initial = 0 , # [doc = " Beginning in this phase, the following variants are disallowed:"] # [doc = " * [`TerminatorKind::FalseUnwind`]"] # [doc = " * [`TerminatorKind::FalseEdge`]"] # [doc = " * [`StatementKind::FakeRead`]"] # [doc = " * [`StatementKind::AscribeUserType`]"] # [doc = " * [`StatementKind::Coverage`] with [`CoverageKind::BlockMarker`] or"] # [doc = "   [`CoverageKind::SpanMarker`]"] # [doc = " * [`Rvalue::Ref`] with `BorrowKind::Fake`"] # [doc = " * [`CastKind::PointerCoercion`] with any of the following:"] # [doc = "   * [`PointerCoercion::ArrayToPointer`]"] # [doc = "   * [`PointerCoercion::MutToConstPointer`]"] # [doc = ""] # [doc = " Furthermore, `Deref` projections must be the first projection within any place (if they"] # [doc = " appear at all)"] PostCleanup = 1 , }}}
mkitem!{mkenum!{# [doc = " See [`MirPhase::Runtime`]."] # [derive (Copy , Clone , TyEncodable , TyDecodable , Debug , PartialEq , Eq , PartialOrd , Ord)] # [derive (HashStable)] pub enum RuntimePhase { # [doc = " In addition to the semantic changes, beginning with this phase, the following variants are"] # [doc = " disallowed:"] # [doc = " * [`TerminatorKind::Yield`]"] # [doc = " * [`TerminatorKind::CoroutineDrop`]"] # [doc = " * [`Rvalue::Aggregate`] for any `AggregateKind` except `Array`"] # [doc = " * [`PlaceElem::OpaqueCast`]"] # [doc = ""] # [doc = " And the following variants are allowed:"] # [doc = " * [`StatementKind::Retag`]"] # [doc = " * [`StatementKind::SetDiscriminant`]"] # [doc = " * [`StatementKind::Deinit`]"] # [doc = ""] # [doc = " Furthermore, `Copy` operands are allowed for non-`Copy` types."] Initial = 0 , # [doc = " Beginning with this phase, the following variant is disallowed:"] # [doc = " * [`ProjectionElem::Deref`] of `Box`"] PostCleanup = 1 , Optimized = 2 , }}}
mkitem!{mkenum!{# [derive (Copy , Clone , Debug , PartialEq , Eq , PartialOrd , Ord , TyEncodable , TyDecodable)] # [derive (Hash , HashStable)] pub enum BorrowKind { # [doc = " Data must be immutable and is aliasable."] Shared , # [doc = " An immutable, aliasable borrow that is discarded after borrow-checking. Can behave either"] # [doc = " like a normal shared borrow or like a special shallow borrow (see [`FakeBorrowKind`])."] # [doc = ""] # [doc = " This is used when lowering index expressions and matches. This is used to prevent code like"] # [doc = " the following from compiling:"] # [doc = " ```compile_fail,E0510"] # [doc = " let mut x: &[_] = &[[0, 1]];"] # [doc = " let y: &[_] = &[];"] # [doc = " let _ = x[0][{x = y; 1}];"] # [doc = " ```"] # [doc = " ```compile_fail,E0510"] # [doc = " let mut x = &Some(0);"] # [doc = " match *x {"] # [doc = "     None => (),"] # [doc = "     Some(_) if { x = &None; false } => (),"] # [doc = "     Some(_) => (),"] # [doc = " }"] # [doc = " ```"] # [doc = " We can also report errors with this kind of borrow differently."] Fake (FakeBorrowKind) , # [doc = " Data is mutable and not aliasable."] Mut { kind : MutBorrowKind } , }}}
mkitem!{mkenum!{# [derive (Copy , Clone , Debug , PartialEq , Eq , PartialOrd , Ord , TyEncodable , TyDecodable)] # [derive (Hash , HashStable)] pub enum RawPtrKind { Mut , Const , # [doc = " Creates a raw pointer to a place that will only be used to access its metadata,"] # [doc = " not the data behind the pointer. Note that this limitation is *not* enforced"] # [doc = " by the validator."] # [doc = ""] # [doc = " The borrow checker allows overlap of these raw pointers with references to the"] # [doc = " data. This is sound even if the pointer is \"misused\" since any such use is anyway"] # [doc = " unsafe. In terms of the operational semantics (i.e., Miri), this is equivalent"] # [doc = " to `RawPtrKind::Mut`, but will never incur a retag."] FakeForPtrMetadata , }}}
mkitem!{mkenum!{# [derive (Copy , Clone , Debug , PartialEq , Eq , PartialOrd , Ord , TyEncodable , TyDecodable)] # [derive (Hash , HashStable)] pub enum MutBorrowKind { Default , # [doc = " This borrow arose from method-call auto-ref. (i.e., `adjustment::Adjust::Borrow`)"] TwoPhaseBorrow , # [doc = " Data must be immutable but not aliasable. This kind of borrow"] # [doc = " cannot currently be expressed by the user and is used only in"] # [doc = " implicit closure bindings. It is needed when the closure is"] # [doc = " borrowing or mutating a mutable referent, e.g.:"] # [doc = " ```"] # [doc = " let mut z = 3;"] # [doc = " let x: &mut isize = &mut z;"] # [doc = " let y = || *x += 5;"] # [doc = " ```"] # [doc = " If we were to try to translate this closure into a more explicit"] # [doc = " form, we'd encounter an error with the code as written:"] # [doc = " ```compile_fail,E0594"] # [doc = " struct Env<'a> { x: &'a &'a mut isize }"] # [doc = " let mut z = 3;"] # [doc = " let x: &mut isize = &mut z;"] # [doc = " let y = (&mut Env { x: &x }, fn_ptr);  // Closure is pair of env and fn"] # [doc = " fn fn_ptr(env: &mut Env) { **env.x += 5; }"] # [doc = " ```"] # [doc = " This is then illegal because you cannot mutate an `&mut` found"] # [doc = " in an aliasable location. To solve, you'd have to translate with"] # [doc = " an `&mut` borrow:"] # [doc = " ```compile_fail,E0596"] # [doc = " struct Env<'a> { x: &'a mut &'a mut isize }"] # [doc = " let mut z = 3;"] # [doc = " let x: &mut isize = &mut z;"] # [doc = " let y = (&mut Env { x: &mut x }, fn_ptr); // changed from &x to &mut x"] # [doc = " fn fn_ptr(env: &mut Env) { **env.x += 5; }"] # [doc = " ```"] # [doc = " Now the assignment to `**env.x` is legal, but creating a"] # [doc = " mutable pointer to `x` is not because `x` is not mutable. We"] # [doc = " could fix this by declaring `x` as `let mut x`. This is ok in"] # [doc = " user code, if awkward, but extra weird for closures, since the"] # [doc = " borrow is hidden."] # [doc = ""] # [doc = " So we introduce a `ClosureCapture` borrow -- user will not have to mark the variable"] # [doc = " containing the mutable reference as `mut`, as they didn't ever"] # [doc = " intend to mutate the mutable reference itself. We still mutable capture it in order to"] # [doc = " mutate the pointed value through it (but not mutating the reference itself)."] # [doc = ""] # [doc = " This solves the problem. For simplicity, we don't give users the way to express this"] # [doc = " borrow, it's just used when translating closures."] ClosureCapture , }}}
mkitem!{mkenum!{# [derive (Copy , Clone , Debug , PartialEq , Eq , PartialOrd , Ord , TyEncodable , TyDecodable)] # [derive (Hash , HashStable)] pub enum FakeBorrowKind { # [doc = " A shared shallow borrow. The immediately borrowed place must be immutable, but projections"] # [doc = " from it don't need to be. For example, a shallow borrow of `a.b` doesn't conflict with a"] # [doc = " mutable borrow of `a.b.c`."] # [doc = ""] # [doc = " This is used when lowering matches: when matching on a place we want to ensure that place"] # [doc = " have the same value from the start of the match until an arm is selected. This prevents this"] # [doc = " code from compiling:"] # [doc = " ```compile_fail,E0510"] # [doc = " let mut x = &Some(0);"] # [doc = " match *x {"] # [doc = "     None => (),"] # [doc = "     Some(_) if { x = &None; false } => (),"] # [doc = "     Some(_) => (),"] # [doc = " }"] # [doc = " ```"] # [doc = " This can't be a shared borrow because mutably borrowing `(*x as Some).0` should not checking"] # [doc = " the discriminant or accessing other variants, because the mutating `(*x as Some).0` can't"] # [doc = " affect the discriminant of `x`. E.g. the following is allowed:"] # [doc = " ```rust"] # [doc = " let mut x = Some(0);"] # [doc = " match x {"] # [doc = "     Some(_)"] # [doc = "         if {"] # [doc = "             if let Some(ref mut y) = x {"] # [doc = "                 *y += 1;"] # [doc = "             };"] # [doc = "             true"] # [doc = "         } => {}"] # [doc = "     _ => {}"] # [doc = " }"] # [doc = " ```"] Shallow , # [doc = " A shared (deep) borrow. Data must be immutable and is aliasable."] # [doc = ""] # [doc = " This is used when lowering deref patterns, where shallow borrows wouldn't prevent something"] # [doc = " like:"] # [doc = " ```compile_fail"] # [doc = " let mut b = Box::new(false);"] # [doc = " match b {"] # [doc = "     deref!(true) => {} // not reached because `*b == false`"] # [doc = "     _ if { *b = true; false } => {} // not reached because the guard is `false`"] # [doc = "     deref!(false) => {} // not reached because the guard changed it"] # [doc = "     // UB because we reached the unreachable."] # [doc = " }"] # [doc = " ```"] Deep , }}}
mkitem!{mkenum!{# [doc = " The various kinds of statements that can appear in MIR."] # [doc = ""] # [doc = " Not all of these are allowed at every [`MirPhase`]. Check the documentation there to see which"] # [doc = " ones you do not have to worry about. The MIR validator will generally enforce such restrictions,"] # [doc = " causing an ICE if they are violated."] # [derive (Clone , Debug , PartialEq , TyEncodable , TyDecodable , Hash , HashStable)] # [derive (TypeFoldable , TypeVisitable)] pub enum StatementKind < 'tcx > { # [doc = " Assign statements roughly correspond to an assignment in Rust proper (`x = ...`) except"] # [doc = " without the possibility of dropping the previous value (that must be done separately, if at"] # [doc = " all). The *exact* way this works is undecided. It probably does something like evaluating"] # [doc = " the LHS to a place and the RHS to a value, and then storing the value to the place. Various"] # [doc = " parts of this may do type specific things that are more complicated than simply copying"] # [doc = " bytes."] # [doc = ""] # [doc = " **Needs clarification**: The implication of the above idea would be that assignment implies"] # [doc = " that the resulting value is initialized. I believe we could commit to this separately from"] # [doc = " committing to whatever part of the memory model we would need to decide on to make the above"] # [doc = " paragraph precise. Do we want to?"] # [doc = ""] # [doc = " Assignments in which the types of the place and rvalue differ are not well-formed."] # [doc = ""] # [doc = " **Needs clarification**: Do we ever want to worry about non-free (in the body) lifetimes for"] # [doc = " the typing requirement in post drop-elaboration MIR? I think probably not - I'm not sure we"] # [doc = " could meaningfully require this anyway. How about free lifetimes? Is ignoring this"] # [doc = " interesting for optimizations? Do we want to allow such optimizations?"] # [doc = ""] # [doc = " **Needs clarification**: We currently require that the LHS place not overlap with any place"] # [doc = " read as part of computation of the RHS for some rvalues (generally those not producing"] # [doc = " primitives). This requirement is under discussion in [#68364]. As a part of this discussion,"] # [doc = " it is also unclear in what order the components are evaluated."] # [doc = ""] # [doc = " [#68364]: https://github.com/rust-lang/rust/issues/68364"] # [doc = ""] # [doc = " See [`Rvalue`] documentation for details on each of those."] Assign (Box < (Place < 'tcx > , Rvalue < 'tcx >) >) , # [doc = " When executed at runtime, this is a nop."] # [doc = ""] # [doc = " During static analysis, a fake read:"] # [doc = " - requires that the value being read is initialized (or, in the case"] # [doc = "   of closures, that it was fully initialized at some point in the past)"] # [doc = " - constitutes a use of a value for the purposes of NLL (i.e. if the"] # [doc = "   value being fake-read is a reference, the lifetime of that reference"] # [doc = "   will be extended to cover the `FakeRead`)"] # [doc = " - but, unlike an actual read, does *not* invalidate any exclusive"] # [doc = "   borrows."] # [doc = ""] # [doc = " See [`FakeReadCause`] for more details on the situations in which a"] # [doc = " `FakeRead` is emitted."] # [doc = ""] # [doc = " Disallowed after drop elaboration."] FakeRead (Box < (FakeReadCause , Place < 'tcx >) >) , # [doc = " Write the discriminant for a variant to the enum Place."] # [doc = ""] # [doc = " This is permitted for both coroutines and ADTs. This does not necessarily write to the"] # [doc = " entire place; instead, it writes to the minimum set of bytes as required by the layout for"] # [doc = " the type."] SetDiscriminant { place : Box < Place < 'tcx > > , variant_index : VariantIdx } , # [doc = " Deinitializes the place."] # [doc = ""] # [doc = " This writes `uninit` bytes to the entire place."] Deinit (Box < Place < 'tcx > >) , # [doc = " `StorageLive` and `StorageDead` statements mark the live range of a local."] # [doc = ""] # [doc = " At any point during the execution of a function, each local is either allocated or"] # [doc = " unallocated. Except as noted below, all locals except function parameters are initially"] # [doc = " unallocated. `StorageLive` statements cause memory to be allocated for the local while"] # [doc = " `StorageDead` statements cause the memory to be freed. In other words,"] # [doc = " `StorageLive`/`StorageDead` act like the heap operations `allocate`/`deallocate`, but for"] # [doc = " stack-allocated local variables. Using a local in any way (not only reading/writing from it)"] # [doc = " while it is unallocated is UB."] # [doc = ""] # [doc = " Some locals have no `StorageLive` or `StorageDead` statements within the entire MIR body."] # [doc = " These locals are implicitly allocated for the full duration of the function. There is a"] # [doc = " convenience method at `rustc_mir_dataflow::storage::always_storage_live_locals` for"] # [doc = " computing these locals."] # [doc = ""] # [doc = " If the local is already allocated, calling `StorageLive` again will implicitly free the"] # [doc = " local and then allocate fresh uninitialized memory. If a local is already deallocated,"] # [doc = " calling `StorageDead` again is a NOP."] StorageLive (Local) , # [doc = " See `StorageLive` above."] StorageDead (Local) , # [doc = " Retag references in the given place, ensuring they got fresh tags."] # [doc = ""] # [doc = " This is part of the Stacked Borrows model. These statements are currently only interpreted"] # [doc = " by miri and only generated when `-Z mir-emit-retag` is passed. See"] # [doc = " <https://internals.rust-lang.org/t/stacked-borrows-an-aliasing-model-for-rust/8153/> for"] # [doc = " more details."] # [doc = ""] # [doc = " For code that is not specific to stacked borrows, you should consider retags to read and"] # [doc = " modify the place in an opaque way."] # [doc = ""] # [doc = " Only `RetagKind::Default` and `RetagKind::FnEntry` are permitted."] Retag (RetagKind , Box < Place < 'tcx > >) , # [doc = " This statement exists to preserve a trace of a scrutinee matched against a wildcard binding."] # [doc = " This is especially useful for `let _ = PLACE;` bindings that desugar to a single"] # [doc = " `PlaceMention(PLACE)`."] # [doc = ""] # [doc = " When executed at runtime, this computes the given place, but then discards"] # [doc = " it without doing a load. `let _ = *ptr;` is fine even if the pointer is dangling."] PlaceMention (Box < Place < 'tcx > >) , # [doc = " Encodes a user's type ascription. These need to be preserved"] # [doc = " intact so that NLL can respect them. For example:"] # [doc = " ```ignore (illustrative)"] # [doc = " let a: T = y;"] # [doc = " ```"] # [doc = " The effect of this annotation is to relate the type `T_y` of the place `y`"] # [doc = " to the user-given type `T`. The effect depends on the specified variance:"] # [doc = ""] # [doc = " - `Covariant` -- requires that `T_y <: T`"] # [doc = " - `Contravariant` -- requires that `T_y :> T`"] # [doc = " - `Invariant` -- requires that `T_y == T`"] # [doc = " - `Bivariant` -- no effect"] # [doc = ""] # [doc = " When executed at runtime this is a nop."] # [doc = ""] # [doc = " Disallowed after drop elaboration."] AscribeUserType (Box < (Place < 'tcx > , UserTypeProjection) > , ty :: Variance) , # [doc = " Carries control-flow-sensitive information injected by `-Cinstrument-coverage`,"] # [doc = " such as where to generate physical coverage-counter-increments during codegen."] # [doc = ""] # [doc = " Coverage statements are used in conjunction with the coverage mappings and other"] # [doc = " information stored in the function's"] # [doc = " [`mir::Body::function_coverage_info`](crate::mir::Body::function_coverage_info)."] # [doc = " (For inlined MIR, take care to look up the *original function's* coverage info.)"] # [doc = ""] # [doc = " Interpreters and codegen backends that don't support coverage instrumentation"] # [doc = " can usually treat this as a no-op."] Coverage (# [type_foldable (identity)] # [type_visitable (ignore)] CoverageKind ,) , # [doc = " Denotes a call to an intrinsic that does not require an unwind path and always returns."] # [doc = " This avoids adding a new block and a terminator for simple intrinsics."] Intrinsic (Box < NonDivergingIntrinsic < 'tcx > >) , # [doc = " Instructs the const eval interpreter to increment a counter; this counter is used to track"] # [doc = " how many steps the interpreter has taken. It is used to prevent the user from writing const"] # [doc = " code that runs for too long or infinitely. Other than in the const eval interpreter, this"] # [doc = " is a no-op."] ConstEvalCounter , # [doc = " No-op. Useful for deleting instructions without affecting statement indices."] Nop , # [doc = " Marker statement indicating where `place` would be dropped."] # [doc = " This is semantically equivalent to `Nop`, so codegen and MIRI should interpret this"] # [doc = " statement as such."] # [doc = " The only use case of this statement is for linting in MIR to detect temporary lifetime"] # [doc = " changes."] BackwardIncompatibleDropHint { # [doc = " Place to drop"] place : Box < Place < 'tcx > > , # [doc = " Reason for backward incompatibility"] reason : BackwardIncompatibleDropReason , } , }}}
mkitem!{mkenum!{# [derive (Clone , TyEncodable , TyDecodable , Debug , PartialEq , Hash , HashStable , TypeFoldable , TypeVisitable)] pub enum NonDivergingIntrinsic < 'tcx > { # [doc = " Denotes a call to the intrinsic function `assume`."] # [doc = ""] # [doc = " The operand must be a boolean. Optimizers may use the value of the boolean to backtrack its"] # [doc = " computation to infer information about other variables. So if the boolean came from a"] # [doc = " `x < y` operation, subsequent operations on `x` and `y` could elide various bound checks."] # [doc = " If the argument is `false`, this operation is equivalent to `TerminatorKind::Unreachable`."] Assume (Operand < 'tcx >) , # [doc = " Denotes a call to the intrinsic function `copy_nonoverlapping`."] # [doc = ""] # [doc = " First, all three operands are evaluated. `src` and `dest` must each be a reference, pointer,"] # [doc = " or `Box` pointing to the same type `T`. `count` must evaluate to a `usize`. Then, `src` and"] # [doc = " `dest` are dereferenced, and `count * size_of::<T>()` bytes beginning with the first byte of"] # [doc = " the `src` place are copied to the contiguous range of bytes beginning with the first byte"] # [doc = " of `dest`."] # [doc = ""] # [doc = " **Needs clarification**: In what order are operands computed and dereferenced? It should"] # [doc = " probably match the order for assignment, but that is also undecided."] # [doc = ""] # [doc = " **Needs clarification**: Is this typed or not, ie is there a typed load and store involved?"] # [doc = " I vaguely remember Ralf saying somewhere that he thought it should not be."] CopyNonOverlapping (CopyNonOverlapping < 'tcx >) , }}}
mkitem!{mkenum!{# [doc = " Describes what kind of retag is to be performed."] # [derive (Copy , Clone , TyEncodable , TyDecodable , Debug , PartialEq , Eq , Hash , HashStable)] # [rustc_pass_by_value] pub enum RetagKind { # [doc = " The initial retag of arguments when entering a function."] FnEntry , # [doc = " Retag preparing for a two-phase borrow."] TwoPhase , # [doc = " Retagging raw pointers."] Raw , # [doc = " A \"normal\" retag."] Default , }}}
mkitem!{mkenum!{# [doc = " The `FakeReadCause` describes the type of pattern why a FakeRead statement exists."] # [derive (Copy , Clone , TyEncodable , TyDecodable , Debug , Hash , HashStable , PartialEq)] pub enum FakeReadCause { # [doc = " A fake read injected into a match guard to ensure that the discriminants"] # [doc = " that are being matched on aren't modified while the match guard is being"] # [doc = " evaluated."] # [doc = ""] # [doc = " At the beginning of each match guard, a [fake borrow][FakeBorrowKind] is"] # [doc = " inserted for each discriminant accessed in the entire `match` statement."] # [doc = ""] # [doc = " Then, at the end of the match guard, a `FakeRead(ForMatchGuard)` is"] # [doc = " inserted to keep the fake borrows alive until that point."] # [doc = ""] # [doc = " This should ensure that you cannot change the variant for an enum while"] # [doc = " you are in the midst of matching on it."] ForMatchGuard , # [doc = " Fake read of the scrutinee of a `match` or destructuring `let`"] # [doc = " (i.e. `let` with non-trivial pattern)."] # [doc = ""] # [doc = " In `match x { ... }`, we generate a `FakeRead(ForMatchedPlace, x)`"] # [doc = " and insert it into the `otherwise_block` (which is supposed to be"] # [doc = " unreachable for irrefutable pattern-matches like `match` or `let`)."] # [doc = ""] # [doc = " This is necessary because `let x: !; match x {}` doesn't generate any"] # [doc = " actual read of x, so we need to generate a `FakeRead` to check that it"] # [doc = " is initialized."] # [doc = ""] # [doc = " If the `FakeRead(ForMatchedPlace)` is being performed with a closure"] # [doc = " that doesn't capture the required upvars, the `FakeRead` within the"] # [doc = " closure is omitted entirely."] # [doc = ""] # [doc = " To make sure that this is still sound, if a closure matches against"] # [doc = " a Place starting with an Upvar, we hoist the `FakeRead` to the"] # [doc = " definition point of the closure."] # [doc = ""] # [doc = " If the `FakeRead` comes from being hoisted out of a closure like this,"] # [doc = " we record the `LocalDefId` of the closure. Otherwise, the `Option` will be `None`."] ForMatchedPlace (Option < LocalDefId >) , # [doc = " A fake read injected into a match guard to ensure that the places"] # [doc = " bound by the pattern are immutable for the duration of the match guard."] # [doc = ""] # [doc = " Within a match guard, references are created for each place that the"] # [doc = " pattern creates a binding for — this is known as the `RefWithinGuard`"] # [doc = " version of the variables. To make sure that the references stay"] # [doc = " alive until the end of the match guard, and properly prevent the"] # [doc = " places in question from being modified, a `FakeRead(ForGuardBinding)`"] # [doc = " is inserted at the end of the match guard."] # [doc = ""] # [doc = " For details on how these references are created, see the extensive"] # [doc = " documentation on `bind_matched_candidate_for_guard` in"] # [doc = " `rustc_mir_build`."] ForGuardBinding , # [doc = " Officially, the semantics of"] # [doc = ""] # [doc = " `let pattern = <expr>;`"] # [doc = ""] # [doc = " is that `<expr>` is evaluated into a temporary and then this temporary is"] # [doc = " into the pattern."] # [doc = ""] # [doc = " However, if we see the simple pattern `let var = <expr>`, we optimize this to"] # [doc = " evaluate `<expr>` directly into the variable `var`. This is mostly unobservable,"] # [doc = " but in some cases it can affect the borrow checker, as in #53695."] # [doc = ""] # [doc = " Therefore, we insert a `FakeRead(ForLet)` immediately after each `let`"] # [doc = " with a trivial pattern."] # [doc = ""] # [doc = " FIXME: `ExprUseVisitor` has an entirely different opinion on what `FakeRead(ForLet)`"] # [doc = " is supposed to mean. If it was accurate to what MIR lowering does,"] # [doc = " would it even make sense to hoist these out of closures like"] # [doc = " `ForMatchedPlace`?"] ForLet (Option < LocalDefId >) , # [doc = " Currently, index expressions overloaded through the `Index` trait"] # [doc = " get lowered differently than index expressions with builtin semantics"] # [doc = " for arrays and slices — the latter will emit code to perform"] # [doc = " bound checks, and then return a MIR place that will only perform the"] # [doc = " indexing \"for real\" when it gets incorporated into an instruction."] # [doc = ""] # [doc = " This is observable in the fact that the following compiles:"] # [doc = ""] # [doc = " ```"] # [doc = " fn f(x: &mut [&mut [u32]], i: usize) {"] # [doc = "     x[i][x[i].len() - 1] += 1;"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " However, we need to be careful to not let the user invalidate the"] # [doc = " bound check with an expression like"] # [doc = ""] # [doc = " `(*x)[1][{ x = y; 4}]`"] # [doc = ""] # [doc = " Here, the first bounds check would be invalidated when we evaluate the"] # [doc = " second index expression. To make sure that this doesn't happen, we"] # [doc = " create a fake borrow of `x` and hold it while we evaluate the second"] # [doc = " index."] # [doc = ""] # [doc = " This borrow is kept alive by a `FakeRead(ForIndex)` at the end of its"] # [doc = " scope."] ForIndex , }}}
mkitem!{mkstruct!{# [derive (Clone , Debug , PartialEq , TyEncodable , TyDecodable , Hash , HashStable)] # [derive (TypeFoldable , TypeVisitable)] pub struct CopyNonOverlapping < 'tcx > { pub src : Operand < 'tcx > , pub dst : Operand < 'tcx > , # [doc = " Number of elements to copy from src to dest, not bytes."] pub count : Operand < 'tcx > , }}}
mkitem!{mkenum!{# [doc = " Represents how a [`TerminatorKind::Call`] was constructed."] # [doc = " Used only for diagnostics."] # [derive (Clone , Copy , TyEncodable , TyDecodable , Debug , PartialEq , Hash , HashStable)] # [derive (TypeFoldable , TypeVisitable)] pub enum CallSource { # [doc = " This came from something such as `a > b` or `a + b`. In THIR, if `from_hir_call`"] # [doc = " is false then this is the desugaring."] OverloadedOperator , # [doc = " This was from comparison generated by a match, used by const-eval for better errors"] # [doc = " when the comparison cannot be done in compile time."] # [doc = ""] # [doc = " (see <https://github.com/rust-lang/rust/issues/90237>)"] MatchCmp , # [doc = " Other types of desugaring that did not come from the HIR, but we don't care about"] # [doc = " for diagnostics (yet)."] Misc , # [doc = " Use of value, generating a clone function call"] Use , # [doc = " Normal function call, no special source"] Normal , }}}
mkitem!{mkenum!{# [derive (Clone , Copy , Debug , TyEncodable , TyDecodable , Hash , HashStable , PartialEq)] # [derive (TypeFoldable , TypeVisitable)] # [doc = " The macro that an inline assembly block was created by"] pub enum InlineAsmMacro { # [doc = " The `asm!` macro"] Asm , # [doc = " The `naked_asm!` macro"] NakedAsm , }}}
mkitem!{mkenum!{# [doc = " The various kinds of terminators, representing ways of exiting from a basic block."] # [doc = ""] # [doc = " A note on unwinding: Panics may occur during the execution of some terminators. Depending on the"] # [doc = " `-C panic` flag, this may either cause the program to abort or the call stack to unwind. Such"] # [doc = " terminators have a `unwind: UnwindAction` field on them. If stack unwinding occurs, then"] # [doc = " once the current function is reached, an action will be taken based on the `unwind` field."] # [doc = " If the action is `Cleanup`, then the execution continues at the given basic block. If the"] # [doc = " action is `Continue` then no cleanup is performed, and the stack continues unwinding."] # [doc = ""] # [doc = " The basic block pointed to by a `Cleanup` unwind action must have its `cleanup` flag set."] # [doc = " `cleanup` basic blocks have a couple restrictions:"] # [doc = "  1. All `unwind` fields in them must be `UnwindAction::Terminate` or `UnwindAction::Unreachable`."] # [doc = "  2. `Return` terminators are not allowed in them. `Terminate` and `Resume` terminators are."] # [doc = "  3. All other basic blocks (in the current body) that are reachable from `cleanup` basic blocks"] # [doc = "     must also be `cleanup`. This is a part of the type system and checked statically, so it is"] # [doc = "     still an error to have such an edge in the CFG even if it's known that it won't be taken at"] # [doc = "     runtime."] # [doc = "  4. The control flow between cleanup blocks must look like an upside down tree. Roughly"] # [doc = "     speaking, this means that control flow that looks like a V is allowed, while control flow"] # [doc = "     that looks like a W is not. This is necessary to ensure that landing pad information can be"] # [doc = "     correctly codegened on MSVC. More precisely:"] # [doc = ""] # [doc = "     Begin with the standard control flow graph `G`. Modify `G` as follows: for any two cleanup"] # [doc = "     vertices `u` and `v` such that `u` dominates `v`, contract `u` and `v` into a single vertex,"] # [doc = "     deleting self edges and duplicate edges in the process. Now remove all vertices from `G`"] # [doc = "     that are not cleanup vertices or are not reachable. The resulting graph must be an inverted"] # [doc = "     tree, that is each vertex may have at most one successor and there may be no cycles."] # [derive (Clone , TyEncodable , TyDecodable , Hash , HashStable , PartialEq , TypeFoldable , TypeVisitable)] pub enum TerminatorKind < 'tcx > { # [doc = " Block has one successor; we continue execution there."] Goto { target : BasicBlock } , # [doc = " Switches based on the computed value."] # [doc = ""] # [doc = " First, evaluates the `discr` operand. The type of the operand must be a signed or unsigned"] # [doc = " integer, char, or bool, and must match the given type. Then, if the list of switch targets"] # [doc = " contains the computed value, continues execution at the associated basic block. Otherwise,"] # [doc = " continues execution at the \"otherwise\" basic block."] # [doc = ""] # [doc = " Target values may not appear more than once."] SwitchInt { # [doc = " The discriminant value being tested."] discr : Operand < 'tcx > , targets : SwitchTargets , } , # [doc = " Indicates that the landing pad is finished and that the process should continue unwinding."] # [doc = ""] # [doc = " Like a return, this marks the end of this invocation of the function."] # [doc = ""] # [doc = " Only permitted in cleanup blocks. `Resume` is not permitted with `-C unwind=abort` after"] # [doc = " deaggregation runs."] UnwindResume , # [doc = " Indicates that the landing pad is finished and that the process should terminate."] # [doc = ""] # [doc = " Used to prevent unwinding for foreign items or with `-C unwind=abort`. Only permitted in"] # [doc = " cleanup blocks."] UnwindTerminate (UnwindTerminateReason) , # [doc = " Returns from the function."] # [doc = ""] # [doc = " Like function calls, the exact semantics of returns in Rust are unclear. Returning very"] # [doc = " likely at least assigns the value currently in the return place (`_0`) to the place"] # [doc = " specified in the associated `Call` terminator in the calling function, as if assigned via"] # [doc = " `dest = move _0`. It might additionally do other things, like have side-effects in the"] # [doc = " aliasing model."] # [doc = ""] # [doc = " If the body is a coroutine body, this has slightly different semantics; it instead causes a"] # [doc = " `CoroutineState::Returned(_0)` to be created (as if by an `Aggregate` rvalue) and assigned"] # [doc = " to the return place."] Return , # [doc = " Indicates a terminator that can never be reached."] # [doc = ""] # [doc = " Executing this terminator is UB."] Unreachable , # [doc = " The behavior of this statement differs significantly before and after drop elaboration."] # [doc = ""] # [doc = " After drop elaboration: `Drop` terminators are a complete nop for types that have no drop"] # [doc = " glue. For other types, `Drop` terminators behave exactly like a call to"] # [doc = " `core::mem::drop_in_place` with a pointer to the given place."] # [doc = ""] # [doc = " `Drop` before drop elaboration is a *conditional* execution of the drop glue. Specifically,"] # [doc = " the `Drop` will be executed if..."] # [doc = ""] # [doc = " **Needs clarification**: End of that sentence. This in effect should document the exact"] # [doc = " behavior of drop elaboration. The following sounds vaguely right, but I'm not quite sure:"] # [doc = ""] # [doc = " > The drop glue is executed if, among all statements executed within this `Body`, an assignment to"] # [doc = " > the place or one of its \"parents\" occurred more recently than a move out of it. This does not"] # [doc = " > consider indirect assignments."] # [doc = ""] # [doc = " The `replace` flag indicates whether this terminator was created as part of an assignment."] # [doc = " This should only be used for diagnostic purposes, and does not have any operational"] # [doc = " meaning."] # [doc = ""] # [doc = " Async drop processing:"] # [doc = " In compiler/rustc_mir_build/src/build/scope.rs we detect possible async drop:"] # [doc = "   drop of object with `needs_async_drop`."] # [doc = " Async drop later, in StateTransform pass, may be expanded into additional yield-point"] # [doc = "   for poll-loop of async drop future."] # [doc = " So we need prepared 'drop' target block in the similar way as for `Yield` terminator"] # [doc = "   (see `drops.build_mir::<CoroutineDrop>` in scopes.rs)."] # [doc = " In compiler/rustc_mir_transform/src/elaborate_drops.rs for object implementing `AsyncDrop` trait"] # [doc = "   we need to prepare async drop feature - resolve `AsyncDrop::drop` and codegen call."] # [doc = " `async_fut` is set to the corresponding local."] # [doc = " For coroutine drop we don't need this logic because coroutine drop works with the same"] # [doc = "   layout object as coroutine itself. So `async_fut` will be `None` for coroutine drop."] # [doc = " Both `drop` and `async_fut` fields are only used in compiler/rustc_mir_transform/src/coroutine.rs,"] # [doc = "   StateTransform pass. In `expand_async_drops` async drops are expanded"] # [doc = "   into one or two yield points with poll ready/pending switch."] # [doc = " When a coroutine has any internal async drop, the coroutine drop function will be async"] # [doc = "   (generated by `create_coroutine_drop_shim_async`, not `create_coroutine_drop_shim`)."] Drop { place : Place < 'tcx > , target : BasicBlock , unwind : UnwindAction , replace : bool , # [doc = " Cleanup to be done if the coroutine is dropped at this suspend point (for async drop)."] drop : Option < BasicBlock > , # [doc = " Prepared async future local (for async drop)"] async_fut : Option < Local > , } , # [doc = " Roughly speaking, evaluates the `func` operand and the arguments, and starts execution of"] # [doc = " the referred to function. The operand types must match the argument types of the function."] # [doc = " The return place type must match the return type. The type of the `func` operand must be"] # [doc = " callable, meaning either a function pointer, a function type, or a closure type."] # [doc = ""] # [doc = " **Needs clarification**: The exact semantics of this. Current backends rely on `move`"] # [doc = " operands not aliasing the return place. It is unclear how this is justified in MIR, see"] # [doc = " [#71117]."] # [doc = ""] # [doc = " [#71117]: https://github.com/rust-lang/rust/issues/71117"] Call { # [doc = " The function that’s being called."] func : Operand < 'tcx > , # [doc = " Arguments the function is called with."] # [doc = " These are owned by the callee, which is free to modify them."] # [doc = " This allows the memory occupied by \"by-value\" arguments to be"] # [doc = " reused across function calls without duplicating the contents."] # [doc = " The span for each arg is also included"] # [doc = " (e.g. `a` and `b` in `x.foo(a, b)`)."] args : Box < [Spanned < Operand < 'tcx > >] > , # [doc = " Where the returned value will be written"] destination : Place < 'tcx > , # [doc = " Where to go after this call returns. If none, the call necessarily diverges."] target : Option < BasicBlock > , # [doc = " Action to be taken if the call unwinds."] unwind : UnwindAction , # [doc = " Where this call came from in HIR/THIR."] call_source : CallSource , # [doc = " This `Span` is the span of the function, without the dot and receiver"] # [doc = " e.g. `foo(a, b)` in `x.foo(a, b)`"] fn_span : Span , } , # [doc = " Tail call."] # [doc = ""] # [doc = " Roughly speaking this is a chimera of [`Call`] and [`Return`], with some caveats."] # [doc = " Semantically tail calls consists of two actions:"] # [doc = " - pop of the current stack frame"] # [doc = " - a call to the `func`, with the return address of the **current** caller"] # [doc = "   - so that a `return` inside `func` returns to the caller of the caller"] # [doc = "     of the function that is currently being executed"] # [doc = ""] # [doc = " Note that in difference with [`Call`] this is missing"] # [doc = " - `destination` (because it's always the return place)"] # [doc = " - `target` (because it's always taken from the current stack frame)"] # [doc = " - `unwind` (because it's always taken from the current stack frame)"] # [doc = ""] # [doc = " [`Call`]: TerminatorKind::Call"] # [doc = " [`Return`]: TerminatorKind::Return"] TailCall { # [doc = " The function that’s being called."] func : Operand < 'tcx > , # [doc = " Arguments the function is called with."] # [doc = " These are owned by the callee, which is free to modify them."] # [doc = " This allows the memory occupied by \"by-value\" arguments to be"] # [doc = " reused across function calls without duplicating the contents."] args : Box < [Spanned < Operand < 'tcx > >] > , # [doc = " This `Span` is the span of the function, without the dot and receiver"] # [doc = " (e.g. `foo(a, b)` in `x.foo(a, b)`"] fn_span : Span , } , # [doc = " Evaluates the operand, which must have type `bool`. If it is not equal to `expected`,"] # [doc = " initiates a panic. Initiating a panic corresponds to a `Call` terminator with some"] # [doc = " unspecified constant as the function to call, all the operands stored in the `AssertMessage`"] # [doc = " as parameters, and `None` for the destination. Keep in mind that the `cleanup` path is not"] # [doc = " necessarily executed even in the case of a panic, for example in `-C panic=abort`. If the"] # [doc = " assertion does not fail, execution continues at the specified basic block."] # [doc = ""] # [doc = " When overflow checking is disabled and this is run-time MIR (as opposed to compile-time MIR"] # [doc = " that is used for CTFE), the following variants of this terminator behave as `goto target`:"] # [doc = " - `OverflowNeg(..)`,"] # [doc = " - `Overflow(op, ..)` if op is add, sub, mul, shl, shr, but NOT div or rem."] Assert { cond : Operand < 'tcx > , expected : bool , msg : Box < AssertMessage < 'tcx > > , target : BasicBlock , unwind : UnwindAction , } , # [doc = " Marks a suspend point."] # [doc = ""] # [doc = " Like `Return` terminators in coroutine bodies, this computes `value` and then a"] # [doc = " `CoroutineState::Yielded(value)` as if by `Aggregate` rvalue. That value is then assigned to"] # [doc = " the return place of the function calling this one, and execution continues in the calling"] # [doc = " function. When next invoked with the same first argument, execution of this function"] # [doc = " continues at the `resume` basic block, with the second argument written to the `resume_arg`"] # [doc = " place. If the coroutine is dropped before then, the `drop` basic block is invoked."] # [doc = ""] # [doc = " Note that coroutines can be (unstably) cloned under certain conditions, which means that"] # [doc = " this terminator can **return multiple times**! MIR optimizations that reorder code into"] # [doc = " different basic blocks needs to be aware of that."] # [doc = " See <https://github.com/rust-lang/rust/issues/95360>."] # [doc = ""] # [doc = " Not permitted in bodies that are not coroutine bodies, or after coroutine lowering."] # [doc = ""] # [doc = " **Needs clarification**: What about the evaluation order of the `resume_arg` and `value`?"] Yield { # [doc = " The value to return."] value : Operand < 'tcx > , # [doc = " Where to resume to."] resume : BasicBlock , # [doc = " The place to store the resume argument in."] resume_arg : Place < 'tcx > , # [doc = " Cleanup to be done if the coroutine is dropped at this suspend point."] drop : Option < BasicBlock > , } , # [doc = " Indicates the end of dropping a coroutine."] # [doc = ""] # [doc = " Semantically just a `return` (from the coroutines drop glue). Only permitted in the same situations"] # [doc = " as `yield`."] # [doc = ""] # [doc = " **Needs clarification**: Is that even correct? The coroutine drop code is always confusing"] # [doc = " to me, because it's not even really in the current body."] # [doc = ""] # [doc = " **Needs clarification**: Are there type system constraints on these terminators? Should"] # [doc = " there be a \"block type\" like `cleanup` blocks for them?"] CoroutineDrop , # [doc = " A block where control flow only ever takes one real path, but borrowck needs to be more"] # [doc = " conservative."] # [doc = ""] # [doc = " At runtime this is semantically just a goto."] # [doc = ""] # [doc = " Disallowed after drop elaboration."] FalseEdge { # [doc = " The target normal control flow will take."] real_target : BasicBlock , # [doc = " A block control flow could conceptually jump to, but won't in"] # [doc = " practice."] imaginary_target : BasicBlock , } , # [doc = " A terminator for blocks that only take one path in reality, but where we reserve the right"] # [doc = " to unwind in borrowck, even if it won't happen in practice. This can arise in infinite loops"] # [doc = " with no function calls for example."] # [doc = ""] # [doc = " At runtime this is semantically just a goto."] # [doc = ""] # [doc = " Disallowed after drop elaboration."] FalseUnwind { # [doc = " The target normal control flow will take."] real_target : BasicBlock , # [doc = " The imaginary cleanup block link. This particular path will never be taken"] # [doc = " in practice, but in order to avoid fragility we want to always"] # [doc = " consider it in borrowck. We don't want to accept programs which"] # [doc = " pass borrowck only when `panic=abort` or some assertions are disabled"] # [doc = " due to release vs. debug mode builds."] unwind : UnwindAction , } , # [doc = " Block ends with an inline assembly block. This is a terminator since"] # [doc = " inline assembly is allowed to diverge."] InlineAsm { # [doc = " Macro used to create this inline asm: one of `asm!` or `naked_asm!`"] asm_macro : InlineAsmMacro , # [doc = " The template for the inline assembly, with placeholders."] # [type_foldable (identity)] # [type_visitable (ignore)] template : & 'tcx [InlineAsmTemplatePiece] , # [doc = " The operands for the inline assembly, as `Operand`s or `Place`s."] operands : Box < [InlineAsmOperand < 'tcx >] > , # [doc = " Miscellaneous options for the inline assembly."] options : InlineAsmOptions , # [doc = " Source spans for each line of the inline assembly code. These are"] # [doc = " used to map assembler errors back to the line in the source code."] # [type_foldable (identity)] # [type_visitable (ignore)] line_spans : & 'tcx [Span] , # [doc = " Valid targets for the inline assembly."] # [doc = " The first element is the fallthrough destination, unless"] # [doc = " asm_macro == InlineAsmMacro::NakedAsm or InlineAsmOptions::NORETURN is set."] targets : Box < [BasicBlock] > , # [doc = " Action to be taken if the inline assembly unwinds. This is present"] # [doc = " if and only if InlineAsmOptions::MAY_UNWIND is set."] unwind : UnwindAction , } , }}}
mkitem!{mkenum!{# [derive (Clone , Copy , Debug , TyEncodable , TyDecodable , Hash , HashStable , PartialEq , Eq , TypeFoldable , TypeVisitable)] pub enum BackwardIncompatibleDropReason { Edition2024 , # [doc = " Used by the `macro_extended_temporary_scopes` lint."] MacroExtendedScope , }}}
mkitem!{mkstruct!{# [derive (Debug , Clone , TyEncodable , TyDecodable , Hash , HashStable , PartialEq)] pub struct SwitchTargets { # [doc = " Possible values. For each value, the location to branch to is found in"] # [doc = " the corresponding element in the `targets` vector."] pub (super) values : SmallVec < [Pu128 ; 1] > , # [doc = " Possible branch targets. The last element of this vector is used for"] # [doc = " the \"otherwise\" branch, so `targets.len() == values.len() + 1` always"] # [doc = " holds."] pub (super) targets : SmallVec < [BasicBlock ; 2] > , }}}
mkitem!{mkenum!{# [doc = " Action to be taken when a stack unwind happens."] # [derive (Copy , Clone , Debug , PartialEq , Eq , TyEncodable , TyDecodable , Hash , HashStable)] # [derive (TypeFoldable , TypeVisitable)] pub enum UnwindAction { # [doc = " No action is to be taken. Continue unwinding."] # [doc = ""] # [doc = " This is similar to `Cleanup(bb)` where `bb` does nothing but `Resume`, but they are not"] # [doc = " equivalent, as presence of `Cleanup(_)` will make a frame non-POF."] Continue , # [doc = " Triggers undefined behavior if unwind happens."] Unreachable , # [doc = " Terminates the execution if unwind happens."] # [doc = ""] # [doc = " Depending on the platform and situation this may cause a non-unwindable panic or abort."] Terminate (UnwindTerminateReason) , # [doc = " Cleanups to be done."] Cleanup (BasicBlock) , }}}
mkitem!{mkenum!{# [doc = " The reason we are terminating the process during unwinding."] # [derive (Copy , Clone , Debug , PartialEq , Eq , TyEncodable , TyDecodable , Hash , HashStable)] # [derive (TypeFoldable , TypeVisitable)] pub enum UnwindTerminateReason { # [doc = " Unwinding is just not possible given the ABI of this function."] Abi , # [doc = " We were already cleaning up for an ongoing unwind, and a *second*, *nested* unwind was"] # [doc = " triggered by the drop glue."] InCleanup , }}}
mkitem!{mkenum!{# [doc = " Information about an assertion failure."] # [derive (Clone , Hash , HashStable , PartialEq , Debug)] # [derive (TyEncodable , TyDecodable , TypeFoldable , TypeVisitable)] pub enum AssertKind < O > { BoundsCheck { len : O , index : O } , Overflow (BinOp , O , O) , OverflowNeg (O) , DivisionByZero (O) , RemainderByZero (O) , ResumedAfterReturn (CoroutineKind) , ResumedAfterPanic (CoroutineKind) , ResumedAfterDrop (CoroutineKind) , MisalignedPointerDereference { required : O , found : O } , NullPointerDereference , InvalidEnumConstruction (O) , }}}
mkitem!{mkenum!{# [derive (Clone , Debug , PartialEq , TyEncodable , TyDecodable , Hash , HashStable)] # [derive (TypeFoldable , TypeVisitable)] pub enum InlineAsmOperand < 'tcx > { In { reg : InlineAsmRegOrRegClass , value : Operand < 'tcx > , } , Out { reg : InlineAsmRegOrRegClass , late : bool , place : Option < Place < 'tcx > > , } , InOut { reg : InlineAsmRegOrRegClass , late : bool , in_value : Operand < 'tcx > , out_place : Option < Place < 'tcx > > , } , Const { value : Box < ConstOperand < 'tcx > > , } , SymFn { value : Box < ConstOperand < 'tcx > > , } , SymStatic { def_id : DefId , } , Label { # [doc = " This represents the index into the `targets` array in `TerminatorKind::InlineAsm`."] target_index : usize , } , }}}
mkitem!{# [doc = " Type for MIR `Assert` terminator error messages."] pub type AssertMessage < 'tcx > = AssertKind < Operand < 'tcx > > ;}
mkitem!{mkstruct!{# [doc = " Places roughly correspond to a \"location in memory.\" Places in MIR are the same mathematical"] # [doc = " object as places in Rust. This of course means that what exactly they are is undecided and part"] # [doc = " of the Rust memory model. However, they will likely contain at least the following pieces of"] # [doc = " information in some form:"] # [doc = ""] # [doc = "  1. The address in memory that the place refers to."] # [doc = "  2. The provenance with which the place is being accessed."] # [doc = "  3. The type of the place and an optional variant index. See [`PlaceTy`][super::PlaceTy]."] # [doc = "  4. Optionally, some metadata. This exists if and only if the type of the place is not `Sized`."] # [doc = ""] # [doc = " We'll give a description below of how all pieces of the place except for the provenance are"] # [doc = " calculated. We cannot give a description of the provenance, because that is part of the"] # [doc = " undecided aliasing model - we only include it here at all to acknowledge its existence."] # [doc = ""] # [doc = " Each local naturally corresponds to the place `Place { local, projection: [] }`. This place has"] # [doc = " the address of the local's allocation and the type of the local."] # [doc = ""] # [doc = " For places that are not locals, ie they have a non-empty list of projections, we define the"] # [doc = " values as a function of the parent place, that is the place with its last [`ProjectionElem`]"] # [doc = " stripped. The way this is computed of course depends on the kind of that last projection"] # [doc = " element:"] # [doc = ""] # [doc = "  - [`Downcast`](ProjectionElem::Downcast): This projection sets the place's variant index to the"] # [doc = "    given one, and makes no other changes. A `Downcast` projection must always be followed"] # [doc = "    immediately by a `Field` projection."] # [doc = "  - [`Field`](ProjectionElem::Field): `Field` projections take their parent place and create a"] # [doc = "    place referring to one of the fields of the type. The resulting address is the parent"] # [doc = "    address, plus the offset of the field. The type becomes the type of the field. If the parent"] # [doc = "    was unsized and so had metadata associated with it, then the metadata is retained if the"] # [doc = "    field is unsized and thrown out if it is sized."] # [doc = ""] # [doc = "    These projections are only legal for tuples, ADTs, closures, and coroutines. If the ADT or"] # [doc = "    coroutine has more than one variant, the parent place's variant index must be set, indicating"] # [doc = "    which variant is being used. If it has just one variant, the variant index may or may not be"] # [doc = "    included - the single possible variant is inferred if it is not included."] # [doc = "  - [`OpaqueCast`](ProjectionElem::OpaqueCast): This projection changes the place's type to the"] # [doc = "    given one, and makes no other changes. A `OpaqueCast` projection on any type other than an"] # [doc = "    opaque type from the current crate is not well-formed."] # [doc = "  - [`ConstantIndex`](ProjectionElem::ConstantIndex): Computes an offset in units of `T` into the"] # [doc = "    place as described in the documentation for the `ProjectionElem`. The resulting address is"] # [doc = "    the parent's address plus that offset, and the type is `T`. This is only legal if the parent"] # [doc = "    place has type `[T;  N]` or `[T]` (*not* `&[T]`). Since such a `T` is always sized, any"] # [doc = "    resulting metadata is thrown out."] # [doc = "  - [`Subslice`](ProjectionElem::Subslice): This projection calculates an offset and a new"] # [doc = "    address in a similar manner as `ConstantIndex`. It is also only legal on `[T; N]` and `[T]`."] # [doc = "    However, this yields a `Place` of type `[T]`, and additionally sets the metadata to be the"] # [doc = "    length of the subslice."] # [doc = "  - [`Index`](ProjectionElem::Index): Like `ConstantIndex`, only legal on `[T; N]` or `[T]`."] # [doc = "    However, `Index` additionally takes a local from which the value of the index is computed at"] # [doc = "    runtime. Computing the value of the index involves interpreting the `Local` as a"] # [doc = "    `Place { local, projection: [] }`, and then computing its value as if done via"] # [doc = "    [`Operand::Copy`]. The array/slice is then indexed with the resulting value. The local must"] # [doc = "    have type `usize`."] # [doc = "  - [`Deref`](ProjectionElem::Deref): Derefs are the last type of projection, and the most"] # [doc = "    complicated. They are only legal on parent places that are references, pointers, or `Box`. A"] # [doc = "    `Deref` projection begins by loading a value from the parent place, as if by"] # [doc = "    [`Operand::Copy`]. It then dereferences the resulting pointer, creating a place of the"] # [doc = "    pointee's type. The resulting address is the address that was stored in the pointer. If the"] # [doc = "    pointee type is unsized, the pointer additionally stored the value of the metadata."] # [doc = ""] # [doc = " The \"validity invariant\" of places is the same as that of raw pointers, meaning that e.g."] # [doc = " `*ptr` on a dangling or unaligned pointer is never UB. (Later doing a load/store on that place"] # [doc = " or turning it into a reference can be UB though!) The only ways for a place computation can"] # [doc = " cause UB are:"] # [doc = " - On a `Deref` projection, we do an actual load of the inner place, with all the usual"] # [doc = "   consequences (the inner place must be based on an aligned pointer, it must point to allocated"] # [doc = "   memory, the aliasig model must allow reads, this must not be a data race)."] # [doc = " - For the projections that perform pointer arithmetic, the offset must in-bounds of an"] # [doc = "   allocation (i.e., the preconditions of `ptr::offset` must be met)."] # [derive (Copy , Clone , PartialEq , Eq , Hash , TyEncodable , HashStable , TypeFoldable , TypeVisitable)] pub struct Place < 'tcx > { pub local : Local , # [doc = " projection out of a place (access a field, deref a pointer, etc)"] pub projection : & 'tcx List < PlaceElem < 'tcx > > , }}}
mkitem!{mkenum!{# [derive (Copy , Clone , Debug , PartialEq , Eq , Hash)] # [derive (TyEncodable , TyDecodable , HashStable , TypeFoldable , TypeVisitable)] pub enum ProjectionElem < V , T > { Deref , # [doc = " A field (e.g., `f` in `_1.f`) is one variant of [`ProjectionElem`]. Conceptually,"] # [doc = " rustc can identify that a field projection refers to either two different regions of memory"] # [doc = " or the same one between the base and the 'projection element'."] # [doc = " Read more about projections in the [rustc-dev-guide][mir-datatypes]"] # [doc = ""] # [doc = " [mir-datatypes]: https://rustc-dev-guide.rust-lang.org/mir/index.html#mir-data-types"] Field (FieldIdx , T) , # [doc = " Index into a slice/array."] # [doc = ""] # [doc = " Note that this does not also dereference, and so it does not exactly correspond to slice"] # [doc = " indexing in Rust. In other words, in the below Rust code:"] # [doc = ""] # [doc = " ```rust"] # [doc = " let x = &[1, 2, 3, 4];"] # [doc = " let i = 2;"] # [doc = " x[i];"] # [doc = " ```"] # [doc = ""] # [doc = " The `x[i]` is turned into a `Deref` followed by an `Index`, not just an `Index`. The same"] # [doc = " thing is true of the `ConstantIndex` and `Subslice` projections below."] Index (V) , # [doc = " These indices are generated by slice patterns. Easiest to explain"] # [doc = " by example:"] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " [X, _, .._, _, _] => { offset: 0, min_length: 4, from_end: false },"] # [doc = " [_, X, .._, _, _] => { offset: 1, min_length: 4, from_end: false },"] # [doc = " [_, _, .._, X, _] => { offset: 2, min_length: 4, from_end: true },"] # [doc = " [_, _, .._, _, X] => { offset: 1, min_length: 4, from_end: true },"] # [doc = " ```"] ConstantIndex { # [doc = " index or -index (in Python terms), depending on from_end"] offset : u64 , # [doc = " The thing being indexed must be at least this long -- otherwise, the"] # [doc = " projection is UB."] # [doc = ""] # [doc = " For arrays this is always the exact length."] min_length : u64 , # [doc = " Counting backwards from end? This is always false when indexing an"] # [doc = " array."] from_end : bool , } , # [doc = " These indices are generated by slice patterns."] # [doc = ""] # [doc = " If `from_end` is true `slice[from..slice.len() - to]`."] # [doc = " Otherwise `array[from..to]`."] Subslice { from : u64 , to : u64 , # [doc = " Whether `to` counts from the start or end of the array/slice."] # [doc = " For `PlaceElem`s this is `true` if and only if the base is a slice."] # [doc = " For `ProjectionKind`, this can also be `true` for arrays."] from_end : bool , } , # [doc = " \"Downcast\" to a variant of an enum or a coroutine."] # [doc = ""] # [doc = " The included Symbol is the name of the variant, used for printing MIR."] # [doc = ""] # [doc = " This operation itself is never UB, all it does is change the type of the place."] Downcast (Option < Symbol > , VariantIdx) , # [doc = " Like an explicit cast from an opaque type to a concrete type, but without"] # [doc = " requiring an intermediate variable."] # [doc = ""] # [doc = " This is unused with `-Znext-solver`."] OpaqueCast (T) , # [doc = " A transmute from an unsafe binder to the type that it wraps. This is a projection"] # [doc = " of a place, so it doesn't necessarily constitute a move out of the binder."] UnwrapUnsafeBinder (T) , # [doc = " A `Subtype(T)` projection is applied to any `StatementKind::Assign` where"] # [doc = " type of lvalue doesn't match the type of rvalue, the primary goal is making subtyping"] # [doc = " explicit during optimizations and codegen."] # [doc = ""] # [doc = " This projection doesn't impact the runtime behavior of the program except for potentially changing"] # [doc = " some type metadata of the interpreter or codegen backend."] # [doc = ""] # [doc = " This goal is achieved with mir_transform pass `Subtyper`, which runs right after"] # [doc = " borrowchecker, as we only care about subtyping that can affect trait selection and"] # [doc = " `TypeId`."] Subtype (T) , }}}
mkitem!{# [doc = " Alias for projections as they appear in places, where the base is a place"] # [doc = " and the index is a local."] pub type PlaceElem < 'tcx > = ProjectionElem < Local , Ty < 'tcx > > ;}
mkitem!{mkenum!{# [doc = " An operand in MIR represents a \"value\" in Rust, the definition of which is undecided and part of"] # [doc = " the memory model. One proposal for a definition of values can be found [on UCG][value-def]."] # [doc = ""] # [doc = " [value-def]: https://github.com/rust-lang/unsafe-code-guidelines/blob/master/wip/value-domain.md"] # [doc = ""] # [doc = " The most common way to create values is via loading a place. Loading a place is an operation"] # [doc = " which reads the memory of the place and converts it to a value. This is a fundamentally *typed*"] # [doc = " operation. The nature of the value produced depends on the type of the conversion. Furthermore,"] # [doc = " there may be other effects: if the type has a validity constraint loading the place might be UB"] # [doc = " if the validity constraint is not met."] # [doc = ""] # [doc = " **Needs clarification:** Is loading a place that has its variant index set well-formed? Miri"] # [doc = " currently implements it, but it seems like this may be something to check against in the"] # [doc = " validator."] # [derive (Clone , PartialEq , TyEncodable , TyDecodable , Hash , HashStable , TypeFoldable , TypeVisitable)] pub enum Operand < 'tcx > { # [doc = " Creates a value by loading the given place."] # [doc = ""] # [doc = " Before drop elaboration, the type of the place must be `Copy`. After drop elaboration there"] # [doc = " is no such requirement."] Copy (Place < 'tcx >) , # [doc = " Creates a value by performing loading the place, just like the `Copy` operand."] # [doc = ""] # [doc = " This *may* additionally overwrite the place with `uninit` bytes, depending on how we decide"] # [doc = " in [UCG#188]. You should not emit MIR that may attempt a subsequent second load of this"] # [doc = " place without first re-initializing it."] # [doc = ""] # [doc = " **Needs clarification:** The operational impact of `Move` is unclear. Currently (both in"] # [doc = " Miri and codegen) it has no effect at all unless it appears in an argument to `Call`; for"] # [doc = " `Call` it allows the argument to be passed to the callee \"in-place\", i.e. the callee might"] # [doc = " just get a reference to this place instead of a full copy. Miri implements this with a"] # [doc = " combination of aliasing model \"protectors\" and putting `uninit` into the place. Ralf"] # [doc = " proposes that we don't want these semantics for `Move` in regular assignments, because"] # [doc = " loading a place should not have side-effects, and the aliasing model \"protectors\" are"] # [doc = " inherently tied to a function call. Are these the semantics we want for MIR? Is this"] # [doc = " something we can even decide without knowing more about Rust's memory model?"] # [doc = ""] # [doc = " [UCG#188]: https://github.com/rust-lang/unsafe-code-guidelines/issues/188"] Move (Place < 'tcx >) , # [doc = " Constants are already semantically values, and remain unchanged."] Constant (Box < ConstOperand < 'tcx > >) , }}}
mkitem!{mkstruct!{# [derive (Clone , Copy , PartialEq , TyEncodable , TyDecodable , Hash , HashStable)] # [derive (TypeFoldable , TypeVisitable)] pub struct ConstOperand < 'tcx > { pub span : Span , # [doc = " Optional user-given type: for something like"] # [doc = " `collect::<Vec<_>>`, this would be present and would"] # [doc = " indicate that `Vec<_>` was explicitly specified."] # [doc = ""] # [doc = " Needed for NLL to impose user-given type constraints."] pub user_ty : Option < UserTypeAnnotationIndex > , pub const_ : Const < 'tcx > , }}}
mkitem!{mkenum!{# [doc = " The various kinds of rvalues that can appear in MIR."] # [doc = ""] # [doc = " Not all of these are allowed at every [`MirPhase`] - when this is the case, it's stated below."] # [doc = ""] # [doc = " Computing any rvalue begins by evaluating the places and operands in some order (**Needs"] # [doc = " clarification**: Which order?). These are then used to produce a \"value\" - the same kind of"] # [doc = " value that an [`Operand`] produces."] # [derive (Clone , TyEncodable , TyDecodable , Hash , HashStable , PartialEq , TypeFoldable , TypeVisitable)] pub enum Rvalue < 'tcx > { # [doc = " Yields the operand unchanged"] Use (Operand < 'tcx >) , # [doc = " Creates an array where each element is the value of the operand."] # [doc = ""] # [doc = " Corresponds to source code like `[x; 32]`."] Repeat (Operand < 'tcx > , ty :: Const < 'tcx >) , # [doc = " Creates a reference of the indicated kind to the place."] # [doc = ""] # [doc = " There is not much to document here, because besides the obvious parts the semantics of this"] # [doc = " are essentially entirely a part of the aliasing model. There are many UCG issues discussing"] # [doc = " exactly what the behavior of this operation should be."] # [doc = ""] # [doc = " `Shallow` borrows are disallowed after drop lowering."] Ref (Region < 'tcx > , BorrowKind , Place < 'tcx >) , # [doc = " Creates a pointer/reference to the given thread local."] # [doc = ""] # [doc = " The yielded type is a `*mut T` if the static is mutable, otherwise if the static is extern a"] # [doc = " `*const T`, and if neither of those apply a `&T`."] # [doc = ""] # [doc = " **Note:** This is a runtime operation that actually executes code and is in this sense more"] # [doc = " like a function call. Also, eliminating dead stores of this rvalue causes `fn main() {}` to"] # [doc = " SIGILL for some reason that I (JakobDegen) never got a chance to look into."] # [doc = ""] # [doc = " **Needs clarification**: Are there weird additional semantics here related to the runtime"] # [doc = " nature of this operation?"] ThreadLocalRef (DefId) , # [doc = " Creates a raw pointer with the indicated mutability to the place."] # [doc = ""] # [doc = " This is generated by pointer casts like `&v as *const _` or raw borrow expressions like"] # [doc = " `&raw const v`."] # [doc = ""] # [doc = " Like with references, the semantics of this operation are heavily dependent on the aliasing"] # [doc = " model."] RawPtr (RawPtrKind , Place < 'tcx >) , # [doc = " Yields the length of the place, as a `usize`."] # [doc = ""] # [doc = " If the type of the place is an array, this is the array length. For slices (`[T]`, not"] # [doc = " `&[T]`) this accesses the place's metadata to determine the length. This rvalue is"] # [doc = " ill-formed for places of other types."] # [doc = ""] # [doc = " This cannot be a `UnOp(PtrMetadata, _)` because that expects a value, and we only"] # [doc = " have a place, and `UnOp(PtrMetadata, RawPtr(place))` is not a thing."] Len (Place < 'tcx >) , # [doc = " Performs essentially all of the casts that can be performed via `as`."] # [doc = ""] # [doc = " This allows for casts from/to a variety of types."] # [doc = ""] # [doc = " **FIXME**: Document exactly which `CastKind`s allow which types of casts."] Cast (CastKind , Operand < 'tcx > , Ty < 'tcx >) , # [doc = " * `Offset` has the same semantics as [`offset`](pointer::offset), except that the second"] # [doc = "   parameter may be a `usize` as well."] # [doc = " * The comparison operations accept `bool`s, `char`s, signed or unsigned integers, floats,"] # [doc = "   raw pointers, or function pointers and return a `bool`. The types of the operands must be"] # [doc = "   matching, up to the usual caveat of the lifetimes in function pointers."] # [doc = " * Left and right shift operations accept signed or unsigned integers not necessarily of the"] # [doc = "   same type and return a value of the same type as their LHS. Like in Rust, the RHS is"] # [doc = "   truncated as needed."] # [doc = " * The `Bit*` operations accept signed integers, unsigned integers, or bools with matching"] # [doc = "   types and return a value of that type."] # [doc = " * The `FooWithOverflow` are like the `Foo`, but returning `(T, bool)` instead of just `T`,"] # [doc = "   where the `bool` is true if the result is not equal to the infinite-precision result."] # [doc = " * The remaining operations accept signed integers, unsigned integers, or floats with"] # [doc = "   matching types and return a value of that type."] BinaryOp (BinOp , Box < (Operand < 'tcx > , Operand < 'tcx >) >) , # [doc = " Computes a value as described by the operation."] NullaryOp (NullOp < 'tcx > , Ty < 'tcx >) , # [doc = " Exactly like `BinaryOp`, but less operands."] # [doc = ""] # [doc = " Also does two's-complement arithmetic. Negation requires a signed integer or a float;"] # [doc = " bitwise not requires a signed integer, unsigned integer, or bool. Both operation kinds"] # [doc = " return a value with the same type as their operand."] UnaryOp (UnOp , Operand < 'tcx >) , # [doc = " Computes the discriminant of the place, returning it as an integer of type"] # [doc = " [`discriminant_ty`]. Returns zero for types without discriminant."] # [doc = ""] # [doc = " The validity requirements for the underlying value are undecided for this rvalue, see"] # [doc = " [#91095]. Note too that the value of the discriminant is not the same thing as the"] # [doc = " variant index; use [`discriminant_for_variant`] to convert."] # [doc = ""] # [doc = " [`discriminant_ty`]: crate::ty::Ty::discriminant_ty"] # [doc = " [#91095]: https://github.com/rust-lang/rust/issues/91095"] # [doc = " [`discriminant_for_variant`]: crate::ty::Ty::discriminant_for_variant"] Discriminant (Place < 'tcx >) , # [doc = " Creates an aggregate value, like a tuple or struct."] # [doc = ""] # [doc = " This is needed because dataflow analysis needs to distinguish"] # [doc = " `dest = Foo { x: ..., y: ... }` from `dest.x = ...; dest.y = ...;` in the case that `Foo`"] # [doc = " has a destructor."] # [doc = ""] # [doc = " Disallowed after deaggregation for all aggregate kinds except `Array` and `Coroutine`. After"] # [doc = " coroutine lowering, `Coroutine` aggregate kinds are disallowed too."] Aggregate (Box < AggregateKind < 'tcx > > , IndexVec < FieldIdx , Operand < 'tcx > >) , # [doc = " Transmutes a `*mut u8` into shallow-initialized `Box<T>`."] # [doc = ""] # [doc = " This is different from a normal transmute because dataflow analysis will treat the box as"] # [doc = " initialized but its content as uninitialized. Like other pointer casts, this in general"] # [doc = " affects alias analysis."] ShallowInitBox (Operand < 'tcx > , Ty < 'tcx >) , # [doc = " A CopyForDeref is equivalent to a read from a place at the"] # [doc = " codegen level, but is treated specially by drop elaboration. When such a read happens, it"] # [doc = " is guaranteed (via nature of the mir_opt `Derefer` in rustc_mir_transform/src/deref_separator)"] # [doc = " that the only use of the returned value is a deref operation, immediately"] # [doc = " followed by one or more projections. Drop elaboration treats this rvalue as if the"] # [doc = " read never happened and just projects further. This allows simplifying various MIR"] # [doc = " optimizations and codegen backends that previously had to handle deref operations anywhere"] # [doc = " in a place."] CopyForDeref (Place < 'tcx >) , # [doc = " Wraps a value in an unsafe binder."] WrapUnsafeBinder (Operand < 'tcx > , Ty < 'tcx >) , }}}
mkitem!{mkenum!{# [derive (Clone , Copy , Debug , PartialEq , Eq , TyEncodable , TyDecodable , Hash , HashStable)] pub enum CastKind { # [doc = " An exposing pointer to address cast. A cast between a pointer and an integer type, or"] # [doc = " between a function pointer and an integer type."] # [doc = " See the docs on `expose_provenance` for more details."] PointerExposeProvenance , # [doc = " An address-to-pointer cast that picks up an exposed provenance."] # [doc = " See the docs on `with_exposed_provenance` for more details."] PointerWithExposedProvenance , # [doc = " Pointer related casts that are done by coercions. Note that reference-to-raw-ptr casts are"] # [doc = " translated into `&raw mut/const *r`, i.e., they are not actually casts."] # [doc = ""] # [doc = " The following are allowed in [`AnalysisPhase::Initial`] as they're needed for borrowck,"] # [doc = " but after that are forbidden (including in all phases of runtime MIR):"] # [doc = " * [`PointerCoercion::ArrayToPointer`]"] # [doc = " * [`PointerCoercion::MutToConstPointer`]"] # [doc = ""] # [doc = " Both are runtime nops, so should be [`CastKind::PtrToPtr`] instead in runtime MIR."] PointerCoercion (PointerCoercion , CoercionSource) , IntToInt , FloatToInt , FloatToFloat , IntToFloat , PtrToPtr , FnPtrToPtr , # [doc = " Reinterpret the bits of the input as a different type."] # [doc = ""] # [doc = " MIR is well-formed if the input and output types have different sizes,"] # [doc = " but running a transmute between differently-sized types is UB."] Transmute , }}}
mkitem!{mkenum!{# [doc = " Represents how a [`CastKind::PointerCoercion`] was constructed."] # [doc = " Used only for diagnostics."] # [derive (Clone , Copy , Debug , PartialEq , Eq , TyEncodable , TyDecodable , Hash , HashStable)] pub enum CoercionSource { # [doc = " The coercion was manually written by the user with an `as` cast."] AsCast , # [doc = " The coercion was automatically inserted by the compiler."] Implicit , }}}
mkitem!{mkenum!{# [derive (Clone , Debug , PartialEq , Eq , TyEncodable , TyDecodable , Hash , HashStable)] # [derive (TypeFoldable , TypeVisitable)] pub enum AggregateKind < 'tcx > { # [doc = " The type is of the element"] Array (Ty < 'tcx >) , Tuple , # [doc = " The second field is the variant index. It's equal to 0 for struct"] # [doc = " and union expressions. The last field is the"] # [doc = " active field number and is present only for union expressions"] # [doc = " -- e.g., for a union expression `SomeUnion { c: .. }`, the"] # [doc = " active field index would identity the field `c`"] Adt (DefId , VariantIdx , GenericArgsRef < 'tcx > , Option < UserTypeAnnotationIndex > , Option < FieldIdx >) , Closure (DefId , GenericArgsRef < 'tcx >) , Coroutine (DefId , GenericArgsRef < 'tcx >) , CoroutineClosure (DefId , GenericArgsRef < 'tcx >) , # [doc = " Construct a raw pointer from the data pointer and metadata."] # [doc = ""] # [doc = " The `Ty` here is the type of the *pointee*, not the pointer itself."] # [doc = " The `Mutability` indicates whether this produces a `*const` or `*mut`."] # [doc = ""] # [doc = " The [`Rvalue::Aggregate`] operands for thus must be"] # [doc = ""] # [doc = " 0. A raw pointer of matching mutability with any [`core::ptr::Thin`] pointee"] # [doc = " 1. A value of the appropriate [`core::ptr::Pointee::Metadata`] type"] # [doc = ""] # [doc = " *Both* operands must always be included, even the unit value if this is"] # [doc = " creating a thin pointer. If you're just converting between thin pointers,"] # [doc = " you may want an [`Rvalue::Cast`] with [`CastKind::PtrToPtr`] instead."] RawPtr (Ty < 'tcx > , Mutability) , }}}
mkitem!{mkenum!{# [derive (Copy , Clone , Debug , PartialEq , Eq , TyEncodable , TyDecodable , Hash , HashStable)] pub enum NullOp < 'tcx > { # [doc = " Returns the size of a value of that type"] SizeOf , # [doc = " Returns the minimum alignment of a type"] AlignOf , # [doc = " Returns the offset of a field"] OffsetOf (& 'tcx List < (VariantIdx , FieldIdx) >) , # [doc = " Returns whether we should perform some UB-checking at runtime."] # [doc = " See the `ub_checks` intrinsic docs for details."] UbChecks , # [doc = " Returns whether we should perform contract-checking at runtime."] # [doc = " See the `contract_checks` intrinsic docs for details."] ContractChecks , }}}
mkitem!{mkenum!{# [derive (Copy , Clone , Debug , PartialEq , Eq , Hash)] # [derive (HashStable , TyEncodable , TyDecodable , TypeFoldable , TypeVisitable)] pub enum UnOp { # [doc = " The `!` operator for logical inversion"] Not , # [doc = " The `-` operator for negation"] Neg , # [doc = " Gets the metadata `M` from a `*const`/`*mut`/`&`/`&mut` to"] # [doc = " `impl Pointee<Metadata = M>`."] # [doc = ""] # [doc = " For example, this will give a `()` from `*const i32`, a `usize` from"] # [doc = " `&mut [u8]`, or a `ptr::DynMetadata<dyn Foo>` (internally a pointer)"] # [doc = " from a `*mut dyn Foo`."] # [doc = ""] # [doc = " Allowed only in [`MirPhase::Runtime`]; earlier it's an intrinsic."] PtrMetadata , }}}
mkitem!{mkenum!{# [derive (Copy , Clone , Debug , PartialEq , Eq , Hash)] # [derive (TyEncodable , TyDecodable , HashStable , TypeFoldable , TypeVisitable)] pub enum BinOp { # [doc = " The `+` operator (addition)"] Add , # [doc = " Like `Add`, but with UB on overflow.  (Integers only.)"] AddUnchecked , # [doc = " Like `Add`, but returns `(T, bool)` of both the wrapped result"] # [doc = " and a bool indicating whether it overflowed."] AddWithOverflow , # [doc = " The `-` operator (subtraction)"] Sub , # [doc = " Like `Sub`, but with UB on overflow.  (Integers only.)"] SubUnchecked , # [doc = " Like `Sub`, but returns `(T, bool)` of both the wrapped result"] # [doc = " and a bool indicating whether it overflowed."] SubWithOverflow , # [doc = " The `*` operator (multiplication)"] Mul , # [doc = " Like `Mul`, but with UB on overflow.  (Integers only.)"] MulUnchecked , # [doc = " Like `Mul`, but returns `(T, bool)` of both the wrapped result"] # [doc = " and a bool indicating whether it overflowed."] MulWithOverflow , # [doc = " The `/` operator (division)"] # [doc = ""] # [doc = " For integer types, division by zero is UB, as is `MIN / -1` for signed."] # [doc = " The compiler should have inserted checks prior to this."] # [doc = ""] # [doc = " Floating-point division by zero is safe, and does not need guards."] Div , # [doc = " The `%` operator (modulus)"] # [doc = ""] # [doc = " For integer types, using zero as the modulus (second operand) is UB,"] # [doc = " as is `MIN % -1` for signed."] # [doc = " The compiler should have inserted checks prior to this."] # [doc = ""] # [doc = " Floating-point remainder by zero is safe, and does not need guards."] Rem , # [doc = " The `^` operator (bitwise xor)"] BitXor , # [doc = " The `&` operator (bitwise and)"] BitAnd , # [doc = " The `|` operator (bitwise or)"] BitOr , # [doc = " The `<<` operator (shift left)"] # [doc = ""] # [doc = " The offset is given by `RHS.rem_euclid(LHS::BITS)`."] # [doc = " In other words, it is (uniquely) determined as follows:"] # [doc = " - it is \"equal modulo LHS::BITS\" to the RHS"] # [doc = " - it is in the range `0..LHS::BITS`"] Shl , # [doc = " Like `Shl`, but is UB if the RHS >= LHS::BITS or RHS < 0"] ShlUnchecked , # [doc = " The `>>` operator (shift right)"] # [doc = ""] # [doc = " The offset is given by `RHS.rem_euclid(LHS::BITS)`."] # [doc = " In other words, it is (uniquely) determined as follows:"] # [doc = " - it is \"equal modulo LHS::BITS\" to the RHS"] # [doc = " - it is in the range `0..LHS::BITS`"] # [doc = ""] # [doc = " This is an arithmetic shift if the LHS is signed"] # [doc = " and a logical shift if the LHS is unsigned."] Shr , # [doc = " Like `Shl`, but is UB if the RHS >= LHS::BITS or RHS < 0"] ShrUnchecked , # [doc = " The `==` operator (equality)"] Eq , # [doc = " The `<` operator (less than)"] Lt , # [doc = " The `<=` operator (less than or equal to)"] Le , # [doc = " The `!=` operator (not equal to)"] Ne , # [doc = " The `>=` operator (greater than or equal to)"] Ge , # [doc = " The `>` operator (greater than)"] Gt , # [doc = " The `<=>` operator (three-way comparison, like `Ord::cmp`)"] # [doc = ""] # [doc = " This is supported only on the integer types and `char`, always returning"] # [doc = " [`rustc_hir::LangItem::OrderingEnum`] (aka [`std::cmp::Ordering`])."] # [doc = ""] # [doc = " [`Rvalue::BinaryOp`]`(BinOp::Cmp, A, B)` returns"] # [doc = " - `Ordering::Less` (`-1_i8`, as a Scalar) if `A < B`"] # [doc = " - `Ordering::Equal` (`0_i8`, as a Scalar) if `A == B`"] # [doc = " - `Ordering::Greater` (`+1_i8`, as a Scalar) if `A > B`"] Cmp , # [doc = " The `ptr.offset` operator"] Offset , }}}
mkitem!{mkenum!{# [derive (Copy , Clone , Debug , PartialEq , Eq , Hash , HashStable)] pub enum AssignOp { AddAssign , SubAssign , MulAssign , DivAssign , RemAssign , BitXorAssign , BitAndAssign , BitOrAssign , ShlAssign , ShrAssign , }}}
mkitem!{mkimpl!{impl From < AssignOp > for BinOp { fn from (op : AssignOp) -> BinOp { match op { AssignOp :: AddAssign => BinOp :: Add , AssignOp :: SubAssign => BinOp :: Sub , AssignOp :: MulAssign => BinOp :: Mul , AssignOp :: DivAssign => BinOp :: Div , AssignOp :: RemAssign => BinOp :: Rem , AssignOp :: BitXorAssign => BinOp :: BitXor , AssignOp :: BitAndAssign => BinOp :: BitAnd , AssignOp :: BitOrAssign => BinOp :: BitOr , AssignOp :: ShlAssign => BinOp :: Shl , AssignOp :: ShrAssign => BinOp :: Shr , } } }}}
